import datetime
from typing import Optional, Union, Literal

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.tracer import tracer


class StoreMethods(BaseClient):
    """
    Методы группы 'Store' из https://im-docs.corp.mail.ru/
    """

    @tracer.start_as_current_span("store.store_buy_free")
    def store_buy_free(
        self,
        store_id: str,
        only_my: Optional[Union[str, int]] = "1",
        suggest: Optional[Union[str, int]] = "1",
        with_emoji: Optional[Union[str, int]] = "1",
    ):
        return self.post(
            path="store/store/buy/free",
            params={
                "aimsid": self.aimsid,
                "client": self.client_name,
                "f": "json",
                "k": self.devId,
                "lang": "ru-ru",
                "only_my": only_my,
                "r": self.getReqId(),
                "suggest": suggest,
                "ts": int(datetime.datetime.now().timestamp()),
                "with_emoji": with_emoji,
            },
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            data={"product": store_id},
        )

    @tracer.start_as_current_span("store.store_showcase")
    def store_showcase(self):
        return self.get(
            path="store/store/showcase/",
            reqId=self.getReqId(),
            aimsid=self.aimsid,
        )

    @tracer.start_as_current_span("store.store_showcase_search")
    def store_showcase_search(self, search: str):
        return self.get(
            path="store/store/showcase/",
            reqId=self.getReqId(),
            aimsid=self.aimsid,
            search=search,
        )

    @tracer.start_as_current_span("store.store_my")
    def store_my(self, only_my: int = 1, suggest: int = 1, with_emoji: int = 1):
        return self.get(
            path="store/store/my/",
            aimsid=self.aimsid,
            client=self.client_name,
            f="json",
            k=self.devId,
            lang="ru-ru",
            only_my=only_my,
            r=self.getReqId(),
            suggest=suggest,
            ts=int(datetime.datetime.now().timestamp()),
            with_emoji=with_emoji,
        )

    @tracer.start_as_current_span("store.store_deletepurchase")
    def store_deletepurchase(self, product_id: int):
        return self.get(
            path="store/store/deletepurchase",
            aimsid=self.aimsid,
            client=self.client_name,
            f="json",
            k=self.devId,
            lang="ru-ru",
            r=self.getReqId(),
            product_id=product_id,
            ts=int(datetime.datetime.now().timestamp()),
        )

    @tracer.start_as_current_span("store.store_order_set")
    def store_order_set(self, priority_dict: dict[str, str]):
        params = {
            "aimsid": self.aimsid,
            "client": self.client_name,
            "f": "json",
            "k": self.devId,
            "lang": "ru-ru",
            "platform": "mac",
            "r": self.getReqId(),
            "ts": int(datetime.datetime.now().timestamp()),
        }

        params.update(priority_dict)

        return self.post(
            path="store/store/order_set",
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            params=params,
            data={"empty": "empty"},
        )

    @tracer.start_as_current_span("store.store_lottie_preview")
    def store_lottie_preview(
        self,
        size: Literal[
            "192",
            "194",
            "600",
            "800",
            "small",
            "medium",
            "large",
            "xlarge",
            "iphone",
            "iphone_retina",
            "mdpi",
            "hdpi",
            "xhdpi",
            "xxhdpi",
            "400",
            "share",
            "review_large",
            "preview_medium",
            "preview_small",
            "listicon_large",
            "listicon_medium",
            "listicon_small",
            "sticker_xxlarge",
            "sticker_xlarge",
            "sticker_large",
            "sticker_medium",
            "sticker_small",
            "icon_large",
            "icon_medium",
            "icon_small",
            "stickerpicker_large",
            "stickerpicker_medium",
            "stickerpicker_small",
            "stickerpicker_xsmall",
        ],
        file_id: str,
    ):
        return self.request(
            method="GET",
            url=f"{self.binary_api_url}" f"/store/lottie/preview/{size}/{file_id}/",
            params={"aimsid": self.aimsid},
        )
